mapper.select:
   SELECT
   	distinct
	T1.TRADE_ID AS busiNo,
    PP.PORTFOLIO_ID AS portfolioId,
    PP.PORTFOLIO_NAME AS portfolioName,
   	T1.SETTLE_DATE AS settleDate,
   	T1.PS AS ps,
   	T1.TRADE_AMT AS tradeAmt,
   	T1.IS_CLEAN AS isClean,
   	T1.CCY AS ccy,
   	case 
   			when T5.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01,jdbcType=VARCHAR} then #{PINAN_ASSET_TYPE_F01,jdbcType=VARCHAR}
   			when T5.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F06,jdbcType=VARCHAR} then #{PINAN_ASSET_TYPE_F02,jdbcType=VARCHAR}
   			when (T5.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F17,jdbcType=VARCHAR}
   				and T5.PROFIT_TYPE = #{PROFIT_TYPE_01,jdbcType=VARCHAR}) then #{PINAN_ASSET_TYPE_F04,jdbcType=VARCHAR}
   			when (T5.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F17,jdbcType=VARCHAR}
   				and T5.PROFIT_TYPE = #{PROFIT_TYPE_02,jdbcType=VARCHAR}) then #{PINAN_ASSET_TYPE_F03,jdbcType=VARCHAR}
   			when T5.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F07,jdbcType=VARCHAR} then #{PINAN_ASSET_TYPE_F05,jdbcType=VARCHAR}
   			when T5.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F18,jdbcType=VARCHAR} then #{PINAN_ASSET_TYPE_F06,jdbcType=VARCHAR}
   			else ''
   	end  as finprodType2,
   	T5.FINPROD_MARKET_ID AS finprodMarketId,
   	T5.FINPROD_ABBR AS finprodAbbr,
   	T4.CUSTOM_CASH_TYPE AS customCashType,
   	T1.F_TRADE_ID AS fTradeId,
   	T6.COUNTER_NAME AS counterId
   FROM 
    TRD_PRODUCT_DEAL T1
    LEFT JOIN FIN_PRODUCT T5 ON T5.FINPROD_ID = T1.FINPROD_ID
    LEFT JOIN MST_COUNTER_PARTY T6 ON T6.COUNTER_ID = T1.COUNTER_ID
    LEFT JOIN PTL_TRADE PT ON T1.TRADE_ID = PT.BUSI_NO
    LEFT JOIN PTL_PORTFOLIO PP ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID
	INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PP.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userName}
   	LEFT JOIN TRD_PRODUCT_DEAL_ADD T4 on T1.TRADE_ID = T4.TRADE_ID

	   	T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F23,jdbcType=VARCHAR}
	   	AND T1.IS_CANCEL = #{YES_OR_NO_N,jdbcType=VARCHAR}
	   	AND T1.TRADE_STATUS = #{TRADE_STATUS_01,jdbcType=VARCHAR}
	   	AND PP.INVEST_YESORNO = 'Y'

	   		AND T1.TRADE_ID = #{busiNo,jdbcType=VARCHAR}


		AND (PP.PORTFOLIO_ID IN

				#{item}

			OR PP.PARENT_PORTFOLIO_ID IN

				#{item}

			)


		AND T1.PS = #{ps,jdbcType=VARCHAR}




			AND T5.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01,jdbcType=VARCHAR}


			AND T5.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F06,jdbcType=VARCHAR}


			AND T5.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F17,jdbcType=VARCHAR}
			AND T5.PROFIT_TYPE = #{PROFIT_TYPE_01,jdbcType=VARCHAR}


			AND T5.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F17,jdbcType=VARCHAR}
			AND T5.PROFIT_TYPE = #{PROFIT_TYPE_02,jdbcType=VARCHAR}


			AND T5.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F07,jdbcType=VARCHAR}


			AND T5.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F18,jdbcType=VARCHAR}




		AND T1.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}


		AND T4.CUSTOM_CASH_TYPE = #{customCashType,jdbcType=VARCHAR}


		AND T1.SETTLE_DATE BETWEEN STR_TO_DATE(#{startDate},'%Y-%m-%d')  AND STR_TO_DATE(#{endDate},'%Y-%m-%d')
